#include "PrinterMenu.hpp"
#include "SetupCommands.hpp"
#include "ShellController.hpp"
#include "StatusRow.hpp"
#include "slic3r/GUI/JusPrin/Home/HomeWebView.hpp"

#include "libslic3r/PresetBundle.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/I18N.hpp"
#include "slic3r/GUI/Plater.hpp"

namespace Slic3r::GUI::JusPrin {

namespace {

wxString nozzle_text(double nozzle) { return wxString::Format("%g mm", nozzle); }

HeaderMenuItem separator()
{
    HeaderMenuItem item;
    item.separator = true;
    item.title     = true; // never focusable; the rule is the whole row
    return item;
}

HeaderMenuItem other_printer(const Home::PrinterEntry& printer)
{
    HeaderMenuItem row;
    row.label = wxString::FromUTF8(printer.name);
    switch (printer.status) {
    case Home::PrinterStatus::Printing:
        row.decoration.status      = StatusTone::Busy;
        row.decoration.status_word = _L("Printing");
        if (printer.progress_percent >= 0)
            row.decoration.status_word += wxString::FromUTF8(" \xC2\xB7 ") + wxString::Format("%d%%", printer.progress_percent);
        break;
    case Home::PrinterStatus::Paused:
        row.decoration.status      = StatusTone::Warning;
        row.decoration.status_word = _L("Paused");
        break;
    case Home::PrinterStatus::NeedsAttention:
        row.decoration.status      = StatusTone::Warning;
        row.decoration.status_word = _L("Needs attention");
        break;
    case Home::PrinterStatus::Ready:
        row.decoration.status      = StatusTone::Positive;
        row.decoration.status_word = _L("Ready");
        break;
    case Home::PrinterStatus::Connected:
        // A print host that answers without saying what it is doing.
        row.decoration.status      = StatusTone::Neutral;
        row.decoration.status_word = _L("Connected");
        break;
    case Home::PrinterStatus::Connecting:
        row.decoration.status      = StatusTone::Neutral;
        row.decoration.status_word = _L("Connecting") + wxString::FromUTF8("\xE2\x80\xA6");
        break;
    case Home::PrinterStatus::NotConnected:
        row.decoration.status      = StatusTone::Neutral;
        row.decoration.status_word = _L("Not connected");
        break;
    }
    return row;
}

} // namespace

PrinterMenu::PrinterMenu(wxWindow* owner, const ShellTheme& theme, Plater& plater)
    : m_plater(plater), m_owner(owner), m_theme(theme) {}

void PrinterMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor)
{
    auto self = std::make_shared<PrinterMenu>(owner, theme, plater);
    self->m_menu = new HeaderMenu(owner, theme, dark, {});
    show_root(self);
    self->m_menu->open(anchor);
    // No dismiss listener: the row callbacks own the controller, so it lives
    // until the last queued callback has run.
}

void PrinterMenu::show_root(const Ptr& self)
{
    auto* menu = self->m_menu.get();
    if (menu == nullptr) return; // the popup went away; nothing to rebuild
    const auto printer    = SetupCommands::current_printer();
    const auto connection = SetupCommands::printer_connection();
    const auto plates     = SetupCommands::bed_types();

    std::vector<HeaderMenuItem> rows;

    // Row 1: the machine and what it is doing. A state JusPrin cannot observe
    // reads as "Not connected" with a plain consequence, never as a guess and
    // never in a warning colour -- the chip makes no claim about the machine.
    HeaderMenuItem machine;
    machine.label           = printer.nickname.empty() ? _L("No printer selected") : printer.nickname;
    machine.decoration.bold = true;
    machine.enabled         = connection.monitor_available && !printer.from_file;
    if (printer.from_file) {
        // Not one of the person's printers, so there is no machine to report
        // on: the row says where the profile came from instead.
        machine.decoration.sub_label      = _L("From the file · not one of your printers");
        machine.decoration.sub_label_tone = StatusTone::Warning;
        machine.decoration.sub_label_role = TextRole::BodySmall;
    } else
    switch (connection.state) {
    case SetupCommands::ConnectionState::Ready:
        machine.decoration.status      = StatusTone::Positive;
        machine.decoration.status_word = _L("Ready");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Printing:
        machine.decoration.status      = StatusTone::Busy;
        machine.decoration.status_word = _L("Printing");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Paused:
        machine.decoration.status      = StatusTone::Warning;
        machine.decoration.status_word = _L("Paused");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Connected:
        // Answers, and does not say what it is doing: no claim either way.
        machine.decoration.status      = StatusTone::Neutral;
        machine.decoration.status_word = _L("Connected");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Offline:
        machine.decoration.status      = StatusTone::Neutral;
        machine.decoration.status_word = _L("Offline");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Checking:
        // A print host not read lately: its window can open meanwhile, and
        // says so itself when the page does not load.
        machine.decoration.status      = StatusTone::Neutral;
        machine.decoration.status_word = _L("Checking connection") + wxString::FromUTF8("\xE2\x80\xA6");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::NotConnected:
        machine.decoration.status      = StatusTone::Neutral;
        machine.decoration.status_word = _L("Not connected");
        // Connect… is deferred to a later slice, so the sub-line states the
        // consequence rather than offering an action that would do nothing.
        machine.decoration.sub_label       = _L("Prints go to a card.");
        machine.decoration.sub_label_role  = TextRole::Label;
        machine.decoration.sub_label_faint = true;
        break;
    }
    if (!connection.print_host_printer.empty() && !printer.from_file)
        machine.invoke = [name = connection.print_host_printer] {
            // The same window as the printer's card on Home: the host's own page.
            if (ShellController* shell = installed_shell())
                shell->home_view()->backend().open_printer_window(name);
        };
    else if (connection.monitor_available && !printer.from_file)
        machine.invoke = [] {
            // The same window as the printer's card on Home.
            const std::string device = SetupCommands::monitored_device();
            if (ShellController* shell = installed_shell(); shell != nullptr && !device.empty())
                shell->home_view()->backend().open_monitor_window(device);
        };
    rows.push_back(std::move(machine));
    rows.push_back(separator());

    // Read-only: a printer's nozzle is fixed by its parent system profile, and
    // changing it here would mean moving the printer to another parent and
    // deciding which of its own settings follow. Prepare only shows it.
    HeaderMenuItem nozzle;
    nozzle.label             = _L("Nozzle");
    nozzle.decoration.detail = nozzle_text(printer.nozzle);
    nozzle.enabled           = false;
    rows.push_back(std::move(nozzle));

    HeaderMenuItem plate;
    plate.label = _L("Plate");
    for (const auto& choice : plates)
        if (choice.current) plate.decoration.detail = choice.label;
    plate.enabled = !plates.empty();
    if (plate.enabled) {
        plate.decoration.trailing = HeaderIcon::Right;
        plate.keeps_open          = true;
        plate.invoke              = [self] { show_plates(self); };
    }
    rows.push_back(std::move(plate));
    rows.push_back(separator());

    // Home already resolves each saved printer's device or print-host state.
    // Use that same reading here so an unselected printer does not silently
    // become "Idle" just because its profile exists.
    const auto saved = installed_shell()->home_view()->backend().printers();
    bool has_other_printers = false;
    for (const Home::PrinterEntry& entry : saved) {
        if (entry.kind != Home::PrinterKind::Named || entry.name == printer.preset_name)
            continue;
        if (!has_other_printers) {
            HeaderMenuItem title;
            title.label = _L("OTHER PRINTERS");
            title.title = true;
            rows.push_back(std::move(title));
            has_other_printers = true;
        }
        HeaderMenuItem other = other_printer(entry);
        other.invoke = [self, name = entry.name] {
            if (!SetupCommands::select_named_printer(self->m_plater, name))
                return; // Orca kept the current printer, including when its prompt was cancelled.
            if (ShellController* shell = installed_shell())
                shell->status_row()->refresh();
        };
        rows.push_back(std::move(other));
    }
    if (has_other_printers)
        rows.push_back(separator());

    // Printer settings and Add a printer open the printer conversation.
    // Settings are about the selected preset, named as Orca keys it: the
    // header shows a stock profile's model instead, which names no preset.
    // Orca's placeholder is no printer at all, so its settings are adding one.
    const bool placeholder = wxGetApp().preset_bundle->printers.get_selected_preset().is_default;
    HeaderMenuItem settings;
    settings.label  = _L("Printer settings…");
    settings.invoke = [preset = placeholder ? std::string() : printer.preset_name] {
        if (ShellController* shell = installed_shell())
            shell->open_printer_conversation(preset);
    };
    rows.push_back(std::move(settings));

    // A calibration of the first slot's filament on this printer; which test
    // is the assistant's question. Board 1 puts it after Printer settings….
    HeaderMenuItem calibrate;
    calibrate.label   = _L("Calibrate…");
    calibrate.enabled = !placeholder && printer.valid;
    if (calibrate.enabled) {
        const auto slots = SetupCommands::filament_slots();
        calibrate.invoke = [name = std::string(printer.nickname.ToUTF8()),
                            filament = slots.empty() ? std::string() : std::string(slots.front().filament.alias.ToUTF8())] {
            if (ShellController* shell = installed_shell())
                shell->start_calibration(name, filament);
        };
    }
    rows.push_back(std::move(calibrate));

    HeaderMenuItem add;
    add.label  = _L("Add a printer…");
    add.invoke = [] {
        if (ShellController* shell = installed_shell())
            shell->open_printer_conversation();
    };
    rows.push_back(std::move(add));

    menu->replace_items(std::move(rows));
}

void PrinterMenu::show_plates(const Ptr& self)
{
    std::vector<HeaderMenuItem> choices;
    for (const auto& choice : SetupCommands::bed_types()) {
        HeaderMenuItem row;
        row.label            = choice.label;
        row.decoration.check = choice.current;
        row.invoke = [self, value = choice.value] { SetupCommands::select_bed_type(self->m_plater, value); };
        choices.push_back(std::move(row));
    }
    show_sublist(self, _L("Plate"), std::move(choices));
}

void PrinterMenu::show_sublist(const Ptr& self, const wxString& title, std::vector<HeaderMenuItem> choices)
{
    auto* menu = self->m_menu.get();
    if (menu == nullptr) return; // the popup went away; nothing to rebuild
    std::vector<HeaderMenuItem> rows;
    HeaderMenuItem back;
    back.label      = title;
    back.icon       = HeaderIcon::Back;
    back.keeps_open = true;
    back.invoke     = [self] { show_root(self); };
    rows.push_back(std::move(back));
    rows.push_back(separator());
    for (auto& choice : choices) rows.push_back(std::move(choice));
    menu->replace_items(std::move(rows));
}

} // namespace Slic3r::GUI::JusPrin

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

